/// Assumes, without verification, that a buffer of bytes contains a NEV and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `NEV`.
#[inline]
pub unsafe fn root_as_nev_unchecked(buf: &[u8]) -> NEV<'_> {
    unsafe { ::flatbuffers::root_unchecked::<NEV>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed NEV and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `NEV`.
#[inline]
pub unsafe fn size_prefixed_root_as_nev_unchecked(buf: &[u8]) -> NEV<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<NEV>(buf) }
}

pub const NEV_IDENTIFIER: &str = "$NEV";

#[inline]
pub fn nev_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, NEV_IDENTIFIER, false)
}

#[inline]
pub fn nev_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, NEV_IDENTIFIER, true)
}

#[inline]
pub fn finish_nev_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<NEV<'a>>
) {
    fbb.finish(root, Some(NEV_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_nev_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<NEV<'a>>
) {
    fbb.finish_size_prefixed(root, Some(NEV_IDENTIFIER));
}
